int checks=0,failures=0;void expect(bool yes,const char* text){++checks;if(!yes){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejects(F fn,int status,const char* text){bool yes=false;try{fn();}catch(const Error& e){yes=!status||e.status==status;}expect(yes,text);}
Json record(Json fields=Json::object()){return {{"type","record"},{"value",std::move(fields)}};}
Json real(double value){return {{"type","real"},{"value",value}};}Json string(const std::string& value){return {{"type","string"},{"value",value}};}Json number(int64_t value){return {{"type","integer"},{"value",value}};}
Capture capture(){Capture value;value.payload=record({{"measurement",real(3.25)}});value.settings=record({{"seed",number(42)}});value.scientificProvenance=record({{"backend",string("independent-test")}});value.executionProvenance=record({{"threads",number(1)},{"elapsed_seconds",real(.1)}});value.sources.push_back({"main","main","real x=3.25;\n% exact bytes\n","C:/first/main.p"});return value;}
void write(const std::filesystem::path& path,const std::string& bytes){std::ofstream file(path,std::ios::binary);file.write(bytes.data(),bytes.size());}
Json taggedProvenance(){Json scientific=record({{"source_hash",string("abc")},{"import_hashes",string("")},{"native_keys",string("")},{"algebra",string("A_gamma_v1")},{"gamma",real(1)},{"language",string("0.2")},{"solver_backend",string("backend")},{"precision_bits",number(53)},{"integer_bits",number(64)}});Json execution=record({{"platform",string("windows")},{"source_directory",string("C:/first")},{"cache_directory",string("C:/cache")},{"dependency_locations",string("")},{"requested_threads",number(1)},{"granted_threads",number(1)},{"compiler_attempts",number(1)},{"cache_hits",number(0)},{"compilation_seconds",real(.1)}});return record({{"format",string("PentarnionProvenance")},{"version",number(1)},{"scientific",scientific},{"execution",execution}});}
#ifdef _WIN32
bool junction(const std::filesystem::path& link,const std::filesystem::path& target){if(!CreateDirectoryW(link.c_str(),nullptr))return false;const auto handle=CreateFileW(link.c_str(),GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT|FILE_FLAG_BACKUP_SEMANTICS,nullptr);if(handle==INVALID_HANDLE_VALUE){RemoveDirectoryW(link.c_str());return false;}const auto print=std::filesystem::absolute(target).native(),substitute=L"\\??\\"+print;struct Header{DWORD tag;WORD length,reserved,substituteOffset,substituteLength,printOffset,printLength;};std::vector<unsigned char> bytes(sizeof(Header)+(substitute.size()+print.size()+2)*sizeof(wchar_t));auto* data=reinterpret_cast<Header*>(bytes.data());data->tag=IO_REPARSE_TAG_MOUNT_POINT;data->substituteOffset=0;data->substituteLength=static_cast<WORD>(substitute.size()*2);data->printOffset=static_cast<WORD>((substitute.size()+1)*2);data->printLength=static_cast<WORD>(print.size()*2);data->length=static_cast<WORD>(bytes.size()-8);auto* path=reinterpret_cast<wchar_t*>(bytes.data()+sizeof(Header));std::copy(substitute.begin(),substitute.end(),path);std::copy(print.begin(),print.end(),path+substitute.size()+1);DWORD returned=0;const bool okay=DeviceIoControl(handle,FSCTL_SET_REPARSE_POINT,bytes.data(),static_cast<DWORD>(bytes.size()),nullptr,0,&returned,nullptr)!=0;CloseHandle(handle);if(!okay)RemoveDirectoryW(link.c_str());return okay;}
#endif
void native(){
    Context context;auto c=capture();const auto base=std::filesystem::temp_directory_path()/("penta-bundle-tests-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(base);auto document=build(c);const auto info=inspect(document,context);expect(info.integrity&&info.compatible&&info.sources==1&&!info.pentarnion,"Versioned typed bundle passes integrity/context validation.");expect(source(document,"main",context)==c.sources.front().bytes,"Exact invocation source bytes round-trip without execution.");c.sources[0].bytes+=std::string("% ")+char(0xff)+char(0);const auto binary=build(c);expect(source(binary,"main",context)==c.sources[0].bytes,"Base64 preserves arbitrary exact source bytes including non-UTF8 comment bytes/NUL.");
    auto later=c;later.executionProvenance=record({{"threads",number(4)},{"elapsed_seconds",real(9)}});later.sources[0].location="D:/another/location.p";const auto runtimeChanged=build(later);expect(binary.at("scientific_hash")==runtimeChanged.at("scientific_hash")&&binary.at("integrity_hash")!=runtimeChanged.at("integrity_hash"),"Scientific identity excludes captured scheduling/path/timing metadata while full integrity includes it.");
    auto stable=capture();stable.payload=record({{"provenance",taggedProvenance()},{"measurement",real(3.25)}});auto volatileCopy=stable;volatileCopy.payload["value"]["provenance"]["value"]["execution"]["value"]["compilation_seconds"]=real(123);expect(build(stable).at("scientific_hash")==build(volatileCopy).at("scientific_hash"),"Only recognized framework provenance.execution is excluded from the scientific payload projection.");auto arbitrary=capture();arbitrary.payload=record({{"execution",record({{"elapsed_seconds",real(1)}})}});auto arbitraryChanged=arbitrary;arbitraryChanged.payload["value"]["execution"]["value"]["elapsed_seconds"]=real(2);expect(build(arbitrary).at("scientific_hash")!=build(arbitraryChanged).at("scientific_hash"),"User data named execution/elapsed_seconds remains scientific rather than being silently removed.");
    const std::string import="function real helper(real x){return x*x;}";const auto id="import:"+penta::ode::detail::sha256(import);c=capture();c.sources.push_back({id,"import",import,"C:/first/helper.p"});c.additionalLocations.emplace_back(id,"C:/second/helper.p");document=build(c);const auto imported=inspect(document,context);expect(imported.sources==2&&document.at("runtime").at("source_locations").size()==3&&source(document,id,context)==import,"Identical import bytes retain their snapshot and every distinct original location.");
    auto corrupt=document;corrupt["payload"]["value"]["measurement"]=real(99);rejects([&]{inspect(corrupt,context);},2,"Corruption is rejected before typed data decoding.");auto future=Json{{"format","PentarnionExperimentBundle"},{"version",2},{"untrusted","error(never execute);"}};expect(inspect(future,context).migration,"Unknown future bundle version explicitly requires migration.");rejects([&]{payload(future,context,false);},1,"Future bundle formats never enter the typed decoder.");
    Context foreign=context;foreign.gamma=.5;rejects([&]{payload(document,foreign,false);},1,"Foreign real gamma context requires explicit opt-in.");expect(payload(document,foreign,true)==c.payload,"Explicit real-only foreign-gamma load preserves the original typed numerical payload.");auto p=capture();p.payload=record({{"p",Json{{"type","pentarnion"},{"value",{1,2,3,4,5}}}}});auto pent=build(p);rejects([&]{payload(pent,foreign,true);},1,"Foreign-gamma typed Pentarnion scalars cannot be relabeled.");p.payload=record({{"p",Json{{"type","pentarnionmatrix"},{"rows",0},{"columns",0},{"value",Json::array()}}}});rejects([&]{payload(build(p),foreign,true);},1,"Even empty typed Pentarnion arrays require their exact context.");p.payload=record({{"field",record({{"format",string("PentarnionND-v1")},{"kind",string("pentarnion")},{"gamma",real(1)}})}});rejects([&]{payload(build(p),foreign,true);},1,"Hidden Pentarnion N-D domain records cannot bypass foreign-context protection.");p.payload=record({{"surface",record({{"format",string("PentarnionSurfaceSolution-v1")},{"width",number(5)},{"gamma",real(1)},{"values",real(0)}})}});rejects([&]{payload(build(p),foreign,true);},1,"Five-coordinate surface domain records are context-bearing.");p=capture();p.settings=record({{"coefficient",Json{{"type","pentarnion"},{"value",{1,0,0,0,0}}}}});rejects([&]{payload(build(p),foreign,true);},1,"Pentarnion-valued scientific settings also prevent foreign-context loads.");auto precision=context;precision.precision=64;expect(inspect(document,precision).migration,"Unsupported precision is an explicit compatibility-migration requirement.");rejects([&]{payload(document,precision,true);},1,"Real opt-in cannot silently migrate numerical precision.");
    const auto file=base/"experiment.json";save(file,document,false);expect(read(file)==document,"Atomic fresh bundle publication preserves all metadata and source data.");rejects([&]{save(file,binary,false);},1,"Default bundle publication refuses an existing path.");auto cancelled=std::make_shared<std::atomic_bool>(true);Limits stopped;stopped.cancellation=cancelled;rejects([&]{save(file,binary,true,stopped);},3,"Cancelled overwrite preserves the previously committed bundle.");expect(read(file)==document,"Prior bundle remains intact after interrupted export.");Limits tooSmall;tooSmall.maximumBytes=32;rejects([&]{save(file,binary,true,tooSmall);},7,"Oversized bundle fails before replacing previous data.");expect(read(file)==document,"Byte-budget export failure cannot erase previous numerical results.");
    const auto project=base/"project",outside=base/"outside";std::filesystem::create_directories(project/"plots");std::filesystem::create_directories(outside);write(project/"plots"/"figure.svg","<svg>data only</svg>");write(outside/"secret.txt","not project data");const auto selected=artifact(project,"figure","plots/figure.svg");expect(selected.hash==penta::ode::detail::sha256("<svg>data only</svg>")&&selected.size==20,"Explicit selected artifacts record actual byte hashes, not executable content.");for(const auto* invalid:{"../outside/secret.txt","/outside/secret.txt","C:/outside/secret.txt","plots/../figure.svg","plots/file:stream","CON","plots./figure.svg"})rejects([&]{artifact(project,"bad",invalid);},1,"Artifact traversal/drive/device/ADS ambiguity is rejected.");
#ifdef _WIN32
    const auto escape=project/"escape";const bool made=junction(escape,outside);if(made){rejects([&]{artifact(project,"escape","escape/secret.txt");},1,"Physical Windows path jail rejects an NTFS junction escaping the project.");RemoveDirectoryW(escape.c_str());}else if(const auto* fixture=std::getenv("PENTA_JUNCTION_TEST_ROOT")){rejects([&]{artifact(std::filesystem::path(fixture),"escape","escape/secret.txt");},1,"Physical Windows path jail rejects the explicitly provided NTFS junction fixture.");}else std::cout<<"SKIP NTFS junction creation is denied by this test environment; provide PENTA_JUNCTION_TEST_ROOT for an existing fixture.\n";
#else
    std::filesystem::create_directory_symlink(outside,project/"escape");rejects([&]{artifact(project,"escape","escape/secret.txt");},1,"Canonical Linux path jail rejects an escaping directory symlink.");
#endif
    auto referenced=capture();referenced.artifacts.push_back(selected);const auto manifest=inspect(build(referenced),context);expect(manifest.artifacts==1,"Artifact references remain external-only and integrity covered.");
}
