void language(){
    penta::language::AnalysisOptions foreign;foreign.gamma=.5;
    penta::runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-bundle-language-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(options.dataDirectory);auto run=[&](const std::string& source,bool good=true,penta::language::AnalysisOptions analysis=penta::language::AnalysisOptions{}){const auto result=penta::runtime::execute(source,analysis,options);expect(result.ok()==good,"Experiment bundle DSL execution matches expected status.");if(good&&!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}return result;};
    const std::string code="record data=options(values=[1,2,3],seed=42);saveexperiment(\"values.json\",data,options(overwrite=1));record loaded=loadexperiment(\"values.json\",data);assert(loaded.values==[1,2,3]);record info=experimentinfo(\"values.json\");assert(info.integrity_valid==1);assert(info.compatible==1);assert(info.workspace_history_included==0);string saved=experimentsource(\"values.json\");assert(saved!=\"\");";run(code);expect(source(read(options.dataDirectory/"values.json"),"main",Context{})==code,"Runtime hook records the exact executed main source bytes.");run("record template_data=options(values=[0,0,0],seed=0);record loaded=loadexperiment(\"values.json\",template_data);",false,foreign);run("record template_data=options(values=[0,0,0],seed=0);record loaded=loadexperiment(\"values.json\",template_data,options(allow_real_context=1));assert(loaded.seed==42);",true,foreign);
    run("record data=options(element=i);saveexperiment(\"penta.json\",data,options(overwrite=1));");run("record typed=options(element=i);record loaded=loadexperiment(\"penta.json\",typed,options(allow_real_context=1));",false,foreign);run("record data=options(value=1);saveanalysis(\"legacy.json\",data);");run("record typed=options(value=0);record loaded=loadanalysis(\"legacy.json\",typed);",false,foreign);
    const auto helper=options.dataDirectory/"helper.p";write(helper,"function real squared(real x){return x*x;}");run("import \"helper.p\" as helper;record data=options(value=helper.squared(3));saveexperiment(\"imports.json\",data,options(overwrite=1));");const auto imports=read(options.dataDirectory/"imports.json");expect(inspect(imports,Context{}).sources==2,"All recursive analyzed import snapshots enter the bundle.");write(helper,"error(\"changed after capture; never execute on load\");");run("record typed=options(value=0.0);record loaded=loadexperiment(\"imports.json\",typed);assert(loaded.value==9);assert(experimentinfo(\"imports.json\").integrity_valid); ");
    penta::runtime::InterpreterSession session;auto cancelled=std::make_shared<std::atomic_bool>(false);auto cancelOptions=options;cancelOptions.cancellation=cancelled;const auto old=build(capture());save(options.dataDirectory/"atomic.json",old,false);std::atomic_bool done=false,ready=false;std::thread watcher([&]{ready=true;try{while(!done.load()){std::error_code error;for(auto it=std::filesystem::directory_iterator(options.dataDirectory,error);!error&&it!=std::filesystem::directory_iterator();it.increment(error)){if(it->path().filename().string().starts_with(".penta-data-")){cancelled->store(true);return;}}std::this_thread::yield();}}catch(...){done=true;}});while(!ready.load())std::this_thread::yield();const std::string padded="real completed=6*7;record data=options(value=completed,padding=\""+std::string(3*1024*1024,'x')+"\");saveexperiment(\"atomic.json\",data,options(overwrite=1));";const auto interrupted=session.runFile(padded,{},cancelOptions);done=true;watcher.join();expect(cancelled->load()&&interrupted.status==penta::runtime::ExecutionStatus::RuntimeError&&!interrupted.runtimeDiagnostics.empty()&&interrupted.runtimeDiagnostics.front().code=="R2053","Cancellation inside bundle publication uses the export-only retained-data error status.");expect(read(options.dataDirectory/"atomic.json")==old,"Interrupted publication keeps the previous committed bundle.");cancelled->store(false);const auto retained=session.submit("display(completed);",{},options);expect(retained.ok()&&retained.output==std::vector<std::string>{"42"},"Completed numerical workspace survives cancellation of its subsequent export.");
    const auto changed=session.submit("use_algebra(\"A_gamma\",gamma=0.5);clear;record fresh=options(value=1);saveexperiment(\"atomic.json\",fresh);",{},options);expect(changed.status==penta::runtime::ExecutionStatus::RuntimeError,"An export error does not bypass the existing algebra-context transaction failure.");const auto original=session.submit("display(completed);",{},options);expect(original.ok()&&original.output==std::vector<std::string>{"42"}&&original.analysis.program.gamma==1,"Original context and numerical workspace survive a failed context-changing export transaction.");
    const auto console=session.submit("saveexperiment(\"console.json\",options(value=completed),options(overwrite=1));",{},options);expect(console.ok()&&source(read(options.dataDirectory/"console.json"),"main",Context{}).starts_with("saveexperiment("),"Console bundles explicitly snapshot the current command rather than claiming earlier workspace source closure.");
}
#endif
